import{mountReviewPositionHud}from'../review-position-hud.mjs';
import{inspectPrologueEndpoints}from'./typed-endpoints.mjs';
/** DEV view only. No warp, recovery execution, save, battle or new RAF. */
export function installPrologueReviewHost({root,canvas,getWorld,environment,clearInput=()=>{},onStatus=()=>{},loadScene,reviewPositionEnabled=import.meta.env?.DEV===true,windowTarget=root.ownerDocument.defaultView}){
 const doc=root.ownerDocument;let scene=null,world=null,baseline=null,disposed=false,loading=false,focused=doc.hasFocus?.()!==false,epoch=0,controller=null,savedSize=null,held=false;
 const current=()=>!disposed&&world&&getWorld()===world,unchanged=()=>{if(!current())return false;if(JSON.stringify(world.snapshot())!==baseline)throw Error('PROLOGUE_DEV_CANONICAL_CHANGED');return true;};
 const bar=doc.createElement('section'),note=doc.createElement('p');note.textContent='프롤로그 선정 바닥 DEV 보행 검토 · 회복 착지 시각화 · 출구3 목적지 준비 중 · 게임 진행/사용자 저장 변경 없음';bar.append(note);
 const hud=mountReviewPositionHud({container:bar,enabled:reviewPositionEnabled,read:()=>{const n=scene?.readNative();return{scene:n?.sceneId,foot:n?.foot,facing:n?.facing,pending:loading}}});
 const report=(w,mine,message)=>{if(!disposed&&getWorld()===w&&epoch===mine)onStatus(message);};
 const clearOwned=()=>{scene?.stop();if(current())clearInput();};
 const close=()=>{const old=scene,own=current();scene=null;old?.dispose();if(own){clearInput();if(savedSize)[canvas.width,canvas.height]=savedSize;}savedSize=null;baseline=null;world=null;held=false;};
 async function enter(){if(disposed||loading||scene)return;const w=getWorld();if(!w||w.map.id!=='world:hub:PROLOGUE'||w.busy||w.inputLocked)throw Error('CURRENT_UNLOCKED_PROLOGUE_REQUIRED');const mine=++epoch;loading=true;controller=new AbortController();clearInput();sync();let next;try{next=await loadScene({signal:controller.signal,sessionEpoch:mine});if(disposed||mine!==epoch||getWorld()!==w){next.dispose();return;}world=w;baseline=JSON.stringify(w.snapshot());scene=next;next=null;savedSize=[canvas.width,canvas.height];canvas.width=960;canvas.height=540;scene.setFocused(focused);held=true;clearInput();report(w,mine,'DEV 선정 회복발판에서 보행합니다. 자동 회복/워프 없음. 조사키를 놓고 새로 누르세요.');}catch(e){report(w,mine,e.message);}finally{next?.dispose();if(!disposed&&mine===epoch){loading=false;sync();}}}
 const enterButton=doc.createElement('button');enterButton.textContent='현재 PROLOGUE에서 선정 바닥 DEV 검토';enterButton.onclick=enter;bar.append(enterButton);
 const back=doc.createElement('button');back.textContent='원래 canonical 화면 복귀';back.onclick=()=>{if(unchanged()){epoch++;close();sync();canvas.focus?.();}};bar.append(back);
 function sync(){if(disposed)return;enterButton.disabled=loading||!!scene;back.disabled=loading||!scene;hud.refresh();}
 const release=()=>{held=false;scene?.releaseAction();},blur=()=>{focused=false;scene?.setFocused(false);clearOwned();release();},focus=()=>{if(disposed||doc.hidden||doc.hasFocus?.()===false)return;focused=true;scene?.setFocused(true);release();sync();},keyup=e=>{if(['z','Z','Enter',' ','a','A'].includes(e.key))release();};
 const visibility=()=>doc.hidden?blur():focus();windowTarget.addEventListener('blur',blur);windowTarget.addEventListener('focus',focus);windowTarget.addEventListener('keyup',keyup,true);doc.addEventListener('visibilitychange',visibility);(root.querySelector('.world-play')??root).prepend(bar);sync();
 return{bar,get active(){return!!scene&&current()},get blocked(){return loading||!!scene},frame(dt,dir,ms){if(scene&&!current()){close();sync();return;}if(!scene||!unchanged())return;scene.frame(focused?dt:0,focused?dir:null);const e=environment.getFrame(world.map);scene.draw(canvas.getContext('2d'),{ms,minutes:e.lighting.minutes});sync();},action(){if(!scene||!unchanged()||held)return{executed:false,reason:'INPUT_RELEASE_REQUIRED'};held=true;clearOwned();const endpoints=inspectPrologueEndpoints();report(world,epoch,'출구3은 원래 목적지/귀환 native 착지 검증 전입니다. 현재 보행 검토에서는 워프하지 않습니다.');return{executed:false,reason:'TARGET_NATIVE_REGISTRATION_PENDING',endpoints};},releaseAction:release,cancel(){clearOwned();release();},pause:blur,resume:focus,dispose(){if(disposed)return;disposed=true;epoch++;controller?.abort();close();hud.dispose();windowTarget.removeEventListener('blur',blur);windowTarget.removeEventListener('focus',focus);windowTarget.removeEventListener('keyup',keyup,true);doc.removeEventListener('visibilitychange',visibility);bar.remove();}};
}
